const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'UGX '+Number(n||0).toLocaleString('en-UG');const store={get:(k,d)=>{try{return JSON.parse(localStorage.getItem('eo_'+k))??d}catch{return d}},set:(k,v)=>localStorage.setItem('eo_'+k,JSON.stringify(v))};
const paths={shop:'M3 10h18l-2-6H5l-2 6zm0 0v3a3 3 0 0 0 5 2 3 3 0 0 0 4 0 3 3 0 0 0 4 0 3 3 0 0 0 5-2v-3M5 16v5h14v-5M9 21v-5h6v5',orders:'M9 3H5v18h14V3h-4M9 2h6v4H9zM8 11h8M8 15h5',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4zM8 10h8M8 14h5',heart:'M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-5 5 8 15 8 15S25 10 20 5z',feedback:'M12 3l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',account:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cart:'M3 3h2l3 12h11l3-9H6M9 21h.01M18 21h.01M9 18h10',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',leaf:'M20 3C6 2 0 13 7 18S22 15 20 3zM5 21 16 8',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4zm-4 10 3 3 5-6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',logout:'M9 3H3v18h6M10 12h12m-4-4 4 4-4 4',send:'m22 2-7 20-4-9L2 9 22 2zM11 13 22 2',check:'m5 12 4 4L19 6'};const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.shop}"/></svg>`;
function food(kind,id='x') {const g='g'+String(id).replace(/\W/g,'');let shapes='';if(kind==='samosa')shapes=`<g transform="translate(17 3)"><path d="M42 120 105 23q6-9 12 0l61 97q5 10-7 13H49q-14-1-7-13" fill="url(#${g})" stroke="#bd7525" stroke-width="2"/><path d="m58 116 53-78 49 79Z" fill="#e9a745"/><path d="m105 43 10 14m-36 22 9 10m43-5 12 13m-42 12 9 8" stroke="#b87927" stroke-width="2" opacity=".45"/></g><g transform="translate(-27 25) rotate(-17 140 80)"><path d="m52 117 59-88q5-7 10 0l60 91q5 10-7 11H59q-13-1-7-14" fill="url(#${g})" stroke="#b97c2c" stroke-width="2"/><path d="m71 112 44-69 45 70" fill="none" stroke="#f6d382" stroke-width="3"/></g>`;else if(kind==='mandazi') shapes=`<g transform="rotate(-10 120 80)"><path d="m48 58 56-28q11-5 17 5l24 45q5 10-5 16l-57 28q-10 5-16-4L43 75q-6-11 5-17" fill="url(#${g})" stroke="#b77b2c" stroke-width="2"/><path d="m55 62 50-23 20 39-49 26Z" fill="#e8b357" opacity=".7"/><path d="m113 67 50-20q12-4 17 8l20 47q4 11-7 16l-50 21q-12 3-17-8l-22-47q-4-11 9-17" fill="url(#${g})" stroke="#b77b2c" stroke-width="2"/><path d="m123 72 43-15 16 43-43 17Z" fill="#efbc69" opacity=".55"/></g>`;else if(kind==='daddies')shapes=Array.from({length:17},(_,i)=>{let x=52+(i%5)*28+(Math.floor(i/5)%2)*7,y=48+Math.floor(i/5)*25;return `<rect x="${x}" y="${y}" width="27" height="22" rx="5" transform="rotate(${(i*31)%60-30} ${x+13} ${y+11})" fill="url(#${g})" stroke="#b47930"/><path d="m${x+5} ${y+5} 13-1" stroke="#f9d997" opacity=".65"/>`}).join('');else if(kind==='tea')shapes=`<ellipse cx="122" cy="128" rx="69" ry="16" fill="#ded8c4"/><path d="M151 61h20q28 4 12 37-8 13-30 8" fill="none" stroke="#e3dfcb" stroke-width="13"/><path d="m74 56 9 62q35 22 70-1l11-61Z" fill="#faf6e7" stroke="#e1d9bf" stroke-width="2"/><ellipse cx="119" cy="55" rx="45" ry="14" fill="#d7c6a3"/><ellipse cx="119" cy="56" rx="39" ry="10" fill="#a97845"/><path d="M99 35q-12-12 2-23m18 23q-12-12 2-23m18 23q-12-12 2-23" stroke="#fff" stroke-width="3" opacity=".7" fill="none"/>`;else if(kind==='juice')shapes=`<ellipse cx="119" cy="139" rx="42" ry="7" fill="#dcd9bc"/><path d="m85 32 8 99q26 14 51 0l9-99Z" fill="#fff9dd" stroke="#e3d8ad" stroke-width="2"/><path d="m88 58 8 70q22 11 45 0l7-70Z" fill="#eebd39"/><ellipse cx="118" cy="58" rx="30" ry="7" fill="#f7d865"/><path d="m124 88 16-77h14" stroke="#759d66" stroke-width="5" fill="none"/><circle cx="152" cy="102" r="27" fill="#efbd3e" stroke="#f8e9a5" stroke-width="5"/><path d="m152 79 0 47m-21-31 42 15m-34 10 27-34" stroke="#fff1ad" stroke-width="2"/>`;else shapes=`<ellipse cx="120" cy="131" rx="75" ry="14" fill="#ddd6be"/><path d="M48 88q72-23 145 0l-7 37q-68 19-132-3Z" fill="#e6b05e"/><path d="M49 88q71-21 144 0l-5 15q-66-16-137 2Z" fill="#8c4d28"/><path d="M49 88q71-22 144 0l-7-40q-67-24-130 0Z" fill="#ebc47c" stroke="#cc9c53"/><path d="M60 51q59-19 117 0" stroke="#f7e0a7" stroke-width="4" fill="none"/>`;return `<svg viewBox="0 0 240 175" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${kind}"><defs><linearGradient id="${g}" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="#f4d18a"/><stop offset=".5" stop-color="#dea449"/><stop offset="1" stop-color="#bd7b2a"/></linearGradient><filter id="s${g}"><feDropShadow dx="1" dy="6" stdDeviation="4" flood-color="#8d6b30" flood-opacity=".2"/></filter></defs><ellipse cx="121" cy="107" rx="91" ry="50" fill="#e5ddc8"/><ellipse cx="120" cy="102" rx="89" ry="49" fill="#fbf8ed" stroke="#e6e0cf" stroke-width="3"/><ellipse cx="120" cy="101" rx="74" ry="39" fill="#f1ecd9"/><g filter="url(#s${g})">${shapes}</g><g fill="#64844f"><ellipse cx="190" cy="131" rx="12" ry="4" transform="rotate(-30 190 131)"/><ellipse cx="202" cy="121" rx="11" ry="4" transform="rotate(-60 202 121)"/><path d="m183 142 24-26" stroke="#78935d" stroke-width="2"/></g></svg>`}
const defaults=[{id:'daddies',name:'Crunchy Daddies',category:'Snacks',description:'Little bites. Big happiness.',price:2000,unit:'pack',kind:'daddies',tag:'BESTSELLER',rating:'4.9',available:true},{id:'mandazi',name:'Golden Mandazi',category:'Bakery',description:'Soft inside, golden outside.',price:1000,unit:'piece',kind:'mandazi',tag:'FRESH DAILY',rating:'4.8',available:true},{id:'samosa',name:'Beef Samosa',category:'Snacks',description:'Crispy, savoury & full of flavour.',price:1500,unit:'piece',kind:'samosa',tag:'POPULAR',rating:'4.9',available:true},{id:'tea',name:'Spiced African Tea',category:'Drinks',description:'A warm cup of comfort.',price:2000,unit:'cup',kind:'tea',rating:'4.8',available:true},{id:'cake',name:'Vanilla Cake Slice',category:'Bakery',description:'A little slice of something sweet.',price:3000,unit:'slice',kind:'cake',rating:'4.7',available:true},{id:'juice',name:'Fresh Passion Juice',category:'Drinks',description:'Freshly squeezed. Naturally good.',price:2500,unit:'cup',kind:'juice',tag:'REFRESHING',rating:'4.9',available:true}];
let products=store.get('products',defaults),cart=store.get('cart',{}),orders=store.get('orders',[]),messages=store.get('messages',[]),feedback=store.get('feedback',[]),favs=store.get('favs',[]),config=window.EDUCATE_CONFIG||store.get('config',{}),profile=null,session=null,sb=null,channel=null;let view='shop',category='All items',search='',adminTab='Orders',chatOrder=null,rating=5,installPrompt=null,pendingEmail=store.get('pendingEmail',''),paymentReady=false;const isDemo=()=>!sb;const role=()=>session&&profile?.id===session.user.id?profile.role:'customer';const staff=()=>['admin','staff'].includes(role());const customerId=()=>session?.user?.id||'demo-customer';const count=()=>Object.values(cart).reduce((a,b)=>a+b,0);const total=()=>Object.entries(cart).reduce((s,[id,q])=>s+(products.find(p=>p.id===id)?.price||0)*q,0);const save=()=>{store.set('products',products);store.set('cart',cart);store.set('orders',orders);store.set('messages',messages);store.set('feedback',feedback);store.set('favs',favs)};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
const pic=(p,suffix='')=>p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:food(p.kind,p.id+suffix);const navItems=[['shop','shop','Explore menu'],['orders','orders','My orders'],['favourites','heart','Favourites'],['chat','chat','Messages'],['feedback','feedback','Feedback']];
function navButton(id,ico,label,mobile=false){return `<button data-action="nav" data-value="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`}
function render(){const name=profile?.name?.split(' ')[0]||'friend';$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="/club-logo.png" alt="MRHS Educate Club"><div>Educate Orders</div></div><div class="navlabel">YOUR EVERYDAY GOODNESS</div><nav class="nav">${navItems.map(n=>navButton(...n)).join('')}${staff()?navButton('admin','grid','Workspace'):''}</nav><div class="sidebar-bottom"><div class="mini-promo">${icon('leaf')}<strong>Good food. Great community.</strong><p>Made fresh, with a little extra love. Every single day.</p></div><button class="workspace" data-action="nav" data-value="account">${icon('account')}<span>${session?'My account':'Account & settings'}</span>${icon('chevron')}</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Educate Orders <span>/</span><b>${({shop:'Explore menu',orders:'My orders',favourites:'Favourites',chat:'Messages',feedback:'Your feedback',account:'Account & settings',admin:'Educate workspace'})[view]}</b></div><div class="brand mobile-brand"><img src="/club-logo.png" alt="MRHS Educate Club"><div>Educate Orders</div></div><div class="topright"><span class="online"><i class="dot" style="${navigator.onLine?'':'background:#d3a655'}"></i>${navigator.onLine?'You’re online':'Offline · saved menu'}</span><button class="iconbtn" aria-label="Notifications" data-action="notifications">${icon('bell')}${orders.length?'<i class="badge-dot"></i>':''}</button><button class="avatar" aria-label="Account" data-action="nav" data-value="account">${esc((profile?.name||'EO').slice(0,2).toUpperCase())}</button></div></header>${isDemo()?`<div class="demo-ribbon">Preview mode · data stays on this device. <button data-action="setup">Connect Supabase</button></div>`:''}<div class="content">${view==='shop'||view==='favourites'?shopPage(name):view==='orders'?ordersPage():view==='chat'?chatPage():view==='feedback'?feedbackPage():view==='admin'?adminPage():accountPage()}<footer class="footer"><div>© ${new Date().getFullYear()} Educate Orders. A little goodness, every day.</div><span><button class="link" data-action="nav" data-value="feedback">Need a hand?</button><button class="link" data-action="privacy">Privacy & data</button></span></footer></div></main><nav class="mobile-nav">${navButton('shop','shop','Explore',true)}${navButton('orders','orders','Orders',true)}<button data-action="cart" aria-label="Open cart">${icon('cart')}<span>My cart</span>${count()?`<b class="nav-count">${count()}</b>`:''}</button>${navButton('chat','chat','Chat',true)}${navButton('account','account','Account',true)}</nav>`;if(view==='chat')scrollChat()}
function shopPage(name){let list=products.filter(p=>p.available!==false&&(category==='All items'||p.category===category)&&(!search||(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase()))&&(view!=='favourites'||favs.includes(p.id)));return `<div class="heading-row"><div><div class="eyebrow">A LITTLE GOODNESS, EVERY DAY</div><h1>${view==='favourites'?'Your favourites':`Hello, ${esc(name)} <span class="wave">👋</span>`}</h1><p class="sub">${view==='favourites'?'The things you love, all in one place.':'Welcome to your everyday goodness.'}</p></div><div class="pickup">${icon('pin')}<div>Your pickup spot<strong>Educate · Main kitchen</strong></div></div></div>${view==='shop'?`<section class="wallet-card"><div class="wallet-top"><span>${icon('cart')} YOUR BASKET</span><span class="wallet-chip">Pickup orders</span></div><div class="wallet-amount">${money(total())}</div><div class="wallet-caption">${count()} ${count()===1?'item':'items'} added · ready when you are</div><div class="wallet-bottom"><span>${icon('pin')} Educate main kitchen</span><button data-action="cart">View basket ${icon('arrow')}</button></div></section><section class="quick-actions" aria-label="Quick actions"><button data-action="browse"><span>${icon('shop')}</span>Order food</button><button data-action="nav" data-value="orders"><span>${icon('orders')}</span>My orders</button><button data-action="nav" data-value="chat"><span>${icon('chat')}</span>Chat with us</button><button data-action="nav" data-value="feedback"><span>${icon('feedback')}</span>Feedback</button></section><section class="airtel-promo"><div><span class="promo-label">FRESH FROM OUR KITCHEN</span><h2>Your favourites.<br>Just a tap away.</h2><p>Freshly made. Happily shared.</p><button data-action="browse">Explore menu ${icon('arrow')}</button></div><div class="promo-food">${food('samosa','redpromo')}</div></section>`:''}<div class="shop-layout"><section id="menu"><div class="section-title"><h2>${view==='favourites'?'Saved with love':'What are you craving?'}</h2><small>${list.length} delicious choices</small></div><div class="filters">${['All items','Snacks','Bakery','Drinks'].map((c,i)=>`<button class="filter ${category===c?'active':''}" data-action="category" data-value="${c}">${i===0?icon('grid'):''}${c}</button>`).join('')}<label class="search">${icon('search')}<input id="search" placeholder="Find a favourite" aria-label="Search products" value="${esc(search)}"></label></div><div class="grid">${list.map(productCard).join('')||'<div class="search-empty">Nothing here just yet. Try another category.</div>'}</div><div class="trustbar"><span>${icon('leaf')} Freshly made daily</span><span>${icon('shield')} Made with care</span><span>${icon('wifi')} Browse offline, anytime</span></div></section><aside>${cartPanel()}</aside></div>`}
function productCard(p){return `<article class="product"><div class="product-photo">${pic(p)}${p.tag?`<span class="tag">${esc(p.tag)}</span>`:''}<button class="heart ${favs.includes(p.id)?'saved':''}" data-action="favourite" data-value="${p.id}" aria-label="Save ${esc(p.name)}" aria-pressed="${favs.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><div class="product-meta"><span>${esc(p.category)} · Freshly made</span><span class="star">★ ${p.rating||'New'}</span></div><h3>${esc(p.name)}</h3><p class="product-desc">${esc(p.description)}</p><div class="product-bottom"><span class="price">${money(p.price)} <small>/ ${esc(p.unit)}</small></span><button class="add" data-action="add" data-value="${p.id}" aria-label="Add ${esc(p.name)} to cart">+</button></div></div></article>`}
function cartPanel(){return `<div class="cart-panel"><div class="cart-title"><h2>${icon('cart')} Your little basket</h2><span class="count">${count()} items</span></div><p class="cart-sub">Good things are on the way.</p>${count()?Object.entries(cart).map(([id,q])=>{let p=products.find(p=>p.id===id);if(!p)return '';return `<div class="cart-item"><div class="cart-thumb">${pic(p,'cart')}</div><div><div class="cart-name">${esc(p.name)}</div><div class="cart-price">${money(p.price)}</div></div><div class="qty"><button data-action="minus" data-value="${id}" aria-label="Remove one ${esc(p.name)}">−</button><span>${q}</span><button data-action="add" data-value="${id}" aria-label="Add one ${esc(p.name)}">+</button></div></div>`}).join(''):`<div class="empty-cart">${icon('cart')}<div>A little empty, a lot of possibility.<br>Add your favourites to get started.</div></div>`}<div class="fulfillment">${icon('shop')}<div><strong>Pickup at Educate</strong>Fresh from the main kitchen</div></div><div class="totals"><div class="total-row"><span>Subtotal</span><span>${money(total())}</span></div><div class="total-row"><span>Pickup fee</span><span style="color:#74925b">Free</span></div><div class="total-row final"><span>Total</span><span>${money(total())}</span></div></div><button class="btn" data-action="checkout" ${count()?'':'disabled'}>${navigator.onLine?'Continue to checkout':'Save offline draft'} ${icon('arrow')}</button><div class="secure">${icon('shield')} Collection or Mobile Money · No automatic charge</div></div>`}
function myOrders(){return staff()?orders:orders.filter(o=>o.customer_id===customerId())}
function ordersPage(){let list=myOrders();return `<div class="heading-row"><div><div class="eyebrow">FROM OUR KITCHEN TO YOU</div><h1>Your orders</h1><p class="sub">Every little craving, taken care of.</p></div><button class="btn light" data-action="refresh">${icon('orders')} Refresh</button></div>${list.length?list.map(o=>`<article class="page-card"><div class="order-head"><div><strong>${esc(o.number)}</strong><p class="sub">${new Date(o.created_at).toLocaleString()}</p></div><span class="status ${o.status==='Draft'?'draft':''}">${esc(o.status)}</span></div><div class="order-lines">${(o.items||[]).map(i=>`${i.qty} × ${esc(i.name)}`).join('<br>')}</div><div class="order-bottom"><strong>${money(o.total)}</strong><div>${o.status==='Draft'?`<button class="btn" data-action="submit-draft" data-value="${o.id}">Submit order</button>`:`<button class="btn soft" data-action="order-chat" data-value="${o.id}">${icon('chat')} Chat with us</button>`}</div></div><p class="sub" style="margin-top:12px">${esc(paymentState(o))} · ${esc(paymentLabel(o))}${o.payment_verified_at?' · Confirmed '+new Date(o.payment_verified_at).toLocaleString():''}</p>${o.payment_method&&o.payment_method!=='collection'&&o.status!=='Draft'&&o.status!=='Cancelled'&&o.payment_status!=='Paid'?`<button class="btn light payment-order-button" data-action="payment-details" data-value="${o.id}">${o.payment_reference?'View / update payment reference':'Payment details · Submit reference'}</button>${o.payment_reference?`<p class="sub">Reference: ${esc(o.payment_reference)} · Please wait for staff verification. Do not pay twice.</p>`:''}`:''}<div class="progress">${['Received','Preparing','Ready','Delivered'].map((s,i)=>`<span class="${['Received','Preparing','Ready','Delivered'].indexOf(o.status)>=i?'done':''}"></span>`).join('')}</div></article>`).join(''):`<div class="empty-state">${icon('orders')}<h2>Your next favourite is waiting</h2><p>No orders yet. Discover something delicious<br>and we’ll take care of the rest.</p><button class="btn" data-action="nav" data-value="shop">Explore the menu ${icon('arrow')}</button></div>`}`}
function chatPage(){let list=myOrders().filter(o=>o.status!=='Draft');if(!chatOrder||!list.some(o=>o.id===chatOrder))chatOrder=list[0]?.id;let o=list.find(o=>o.id===chatOrder),msgs=messages.filter(m=>m.order_id===chatOrder);return `<div class="heading-row"><div><div class="eyebrow">A REAL PERSON, A LITTLE HELP</div><h1>Let’s talk</h1><p class="sub">Questions, special requests, or just checking in.</p></div></div>${!list.length?`<div class="empty-state">${icon('chat')}<h2>We’re here for you</h2><p>Place an order to start a conversation with the Educate team.<br>You can also send general feedback anytime.</p><button class="btn" data-action="nav" data-value="feedback">Send feedback</button></div>`:`${isDemo()?'<div class="notice">Demo chat is saved on this device only. Staff access requires a real authorised login. Connect Supabase for shared live conversations.</div>':''}<div class="chat-layout"><div class="chat-list">${list.map(o=>`<button data-action="select-chat" data-value="${o.id}" style="${o.id!==chatOrder?'background:#f8f9f4':''}">${esc(o.number)}<small>${esc(o.customer_name)} · ${esc(o.status)}</small></button>`).join('')}</div><div class="chat-main"><div class="chat-heading">${staff()?esc(o?.customer_name):'Educate kitchen team'} <span class="status" style="float:right">${esc(o?.number)}</span></div><div class="messages">${msgs.length?msgs.map(m=>`<div class="bubble ${m.sender_id===customerId()&&m.sender_role===role()?'me':''}">${esc(m.body)}<small>${esc(m.sender_role)} · ${new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div>`).join(''):'<p class="sub" style="text-align:center;margin:auto">This is the start of your conversation.<br>Say hello to the team!</p>'}</div><form id="chat-form" class="chat-compose"><input name="body" required maxlength="2000" placeholder="Write a message…" aria-label="Message"><button class="btn" ${navigator.onLine?'':'disabled'} aria-label="Send message">${icon('send')}</button></form></div></div>`}`}
function feedbackPage(){return `<div class="heading-row"><div><div class="eyebrow">YOUR VOICE MATTERS</div><h1>A little feedback, a lot of good.</h1><p class="sub">Tell us what you loved, or what we can do better.</p></div></div><div class="page-card account-panel"><form id="feedback-form"><label class="field">How was your experience?</label><div class="rating">${[1,2,3,4,5].map(i=>`<button type="button" class="${rating>=i?'on':''}" data-action="rate" data-value="${i}" aria-label="${i} stars">★</button>`).join('')}</div><label class="field">Your name<input name="name" required maxlength="100" placeholder="Your name" value="${esc(profile?.name||'')}"></label><label class="field">Your feedback<textarea name="body" required maxlength="2000" placeholder="We’re listening…"></textarea></label><button class="btn" ${navigator.onLine?'':'disabled'}>Send feedback ${icon('arrow')}</button><p class="sub" style="margin-top:15px">${navigator.onLine?'Your feedback is shared with the Educate admin.':'Please reconnect to send feedback.'}</p></form></div>`}
function accountPage(){return `<div class="heading-row"><div><div class="eyebrow">YOUR EDUCATE CORNER</div><h1>Account & settings</h1><p class="sub">A few things to make yourself at home.</p></div></div><div class="page-card account-panel">${session?`<h2>${esc(profile?.name||session.user.email)}</h2><p class="sub">${esc(session.user.email)} · ${esc(role())}</p><div class="settings-row"><span>Signed in securely with Supabase</span><button class="btn light" data-action="logout">Sign out</button></div>`:`<h2>Good things start here.</h2><p class="sub" style="margin-top:10px">Create an account to keep your orders and conversations together.</p><div style="display:flex;gap:10px;margin:20px 0"><button class="btn" data-action="login">Log in</button><button class="btn light" data-action="signup">Create account</button></div>`}${isDemo()?`<div class="notice">Customer preview only. Management tools require a real login with an admin or staff role assigned in Supabase. There is no public role switch.</div>`:''}${staff()?`<div class="settings-row"><div><strong>Educate workspace</strong><p>Manage orders and products${role()==='admin'?', people and feedback':''}.</p></div><button class="btn soft" data-action="nav" data-value="admin">Open ${icon('arrow')}</button></div>`:''}<div class="settings-row"><div><strong>Offline-ready menu</strong><p>Products and your basket are saved on this device.<br>Live actions need internet.</p></div>${icon('wifi')}</div><div class="settings-row"><div><strong>Install on your phone</strong><p>Add Educate Orders to your home screen.</p></div><button class="btn light" data-action="install">Install</button></div><div class="settings-row"><div><strong>Notifications</strong><p>In-app live updates while open. Background push is not configured.</p></div><button class="btn light" data-action="notify-permission">Enable</button></div>${isDemo()||role()==='admin'?`<div class="settings-row"><div><strong>Supabase connection</strong><p>${sb?'Connected to your project':'Connect your own project to go live.'}</p></div><button class="btn light" data-action="setup">Configure</button></div>`:''}<div class="settings-row"><div><strong>Feedback</strong><p>Help us serve you a little better.</p></div><button class="btn light" data-action="nav" data-value="feedback">Share</button></div></div>`}
function adminPage(){if(!staff())return '<div class="notice">This workspace requires a staff or admin account.</div>';let admin=role()==='admin';let tabs=admin?['Orders','Products','Users','Feedback']:['Orders','Products'];if(!tabs.includes(adminTab))adminTab='Orders';return `<div class="heading-row"><div><div class="eyebrow">THE GOODNESS BEHIND THE SCENES</div><h1>Kitchen workspace</h1><p class="sub">${admin?'Your products, people, and orders. All together.':'Keep every order moving and every customer happy.'}${!paymentReady?' Mobile Money setup pending: run manual-payments.sql.':''}</p></div><button class="btn light" data-action="refresh">Refresh</button></div><div class="stats"><div class="stat"><small>Total orders</small><strong>${orders.filter(o=>o.status!=='Draft').length}</strong><small>Every craving counted</small></div><div class="stat"><small>In the kitchen</small><strong>${orders.filter(o=>['Received','Preparing'].includes(o.status)).length}</strong><small>Ready for your care</small></div><div class="stat"><small>Collected payments</small><strong style="font-size:20px">${money(orders.filter(o=>o.payment_status==='Paid').reduce((s,o)=>s+Number(o.total),0))}</strong><small>Recorded on collection</small></div><div class="stat"><small>On the menu</small><strong>${products.filter(p=>p.available).length}</strong><small>Fresh possibilities</small></div></div><div class="tabs">${tabs.map(t=>`<button class="filter ${adminTab===t?'active':''}" data-action="admin-tab" data-value="${t}">${t}</button>`).join('')}${adminTab==='Products'?'<button class="btn" style="margin-left:auto" data-action="new-product">+ Add product</button>':''}</div><div class="page-card">${adminTab==='Orders'?adminOrders():adminTab==='Products'?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Availability</th><th>Manage</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.name)}<p class="sub">${esc(p.category)}</p></td><td>${money(p.price)}</td><td><span class="status">${p.available?'Available':'Hidden'}</span></td><td><button class="btn light" data-action="edit-product" data-value="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:adminTab==='Users'?`<h2>People at Educate</h2><p class="sub" style="margin:10px 0 15px">Roles are protected by database policies. Only an admin can change them.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>${(isDemo()?[{id:'demo-customer',name:'Demo customer',email:'Local preview',role:'customer'},{id:'demo-staff',name:'Kitchen team',email:'Local preview',role:'staff'},{id:'demo-admin',name:'Administrator',email:'Local preview',role:'admin'}]:store.get('profiles',[])).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.email)}</td><td>${isDemo()?esc(p.role):`<select data-user-role="${p.id}">${['customer','staff','admin'].map(r=>`<option ${p.role===r?'selected':''}>${r}</option>`).join('')}</select>`}</td></tr>`).join('')}</tbody></table></div>`:`<h2>Customer voices</h2>${feedback.length?feedback.map(f=>`<div class="review"><div><strong>${esc(f.name)}</strong><p style="line-height:1.7;margin:8px 0">${esc(f.body)}</p><small style="color:#8f9786">${new Date(f.created_at).toLocaleDateString()}</small></div><span style="color:#b49443">${'★'.repeat(f.rating)}</span></div>`).join(''):'<p class="sub" style="margin-top:20px">No feedback yet.</p>'}`}</div>`}
function adminOrders(){let list=orders.filter(o=>o.status!=='Draft');return list.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer / items</th><th>Total</th><th>Status</th><th>Payment</th><th>Chat</th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${esc(o.number)}</strong><p class="sub">${new Date(o.created_at).toLocaleDateString()}</p></td><td>${esc(o.customer_name)}<p class="sub">${esc(o.phone||'')}<br>${o.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(', ')}<br>${esc(o.notes||'')}</p></td><td>${money(o.total)}</td><td><select data-status="${o.id}">${['Received','Preparing','Ready','Delivered','Cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td><td><span class="status">${esc(paymentState(o))}</span><p class="sub">${esc(paymentLabel(o))}${o.payment_reference?'<br>Ref: '+esc(o.payment_reference):''}${o.payment_verified_at?'<br>Verified '+new Date(o.payment_verified_at).toLocaleString():''}</p>${o.payment_status!=='Paid'&&o.status!=='Cancelled'?`<button class="btn soft" data-action="verify-payment" data-value="${o.id}" ${o.payment_method&&o.payment_method!=='collection'&&!o.payment_reference?'disabled':''}>Confirm received</button>`:''}</td><td><button class="btn soft" data-action="order-chat" data-value="${o.id}">${icon('chat')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state" style="border:0">'+icon('orders')+'<h2>A fresh start</h2><p>New orders will appear here. Place a demo order from the menu to try it.</p></div>'}
function modal(title,body){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close">×</button></div>${body}</section></div>`;setTimeout(()=>$('#modal-root input')?.focus(),50)}function close(){$('#modal-root').innerHTML=''}
function authForm(signup=false){modal(signup?'A little hello.':'Welcome back.',`<p class="sub">${signup?'Join the Educate community. Your favourites are waiting.':'Good to see you. Let’s get something delicious.'}</p>${isDemo()?'<div class="notice">Connect Supabase in Account & settings to enable real accounts. Demo shopping does not require a login.</div>':''}<form id="auth-form" data-signup="${signup}"><div id="auth-error" class="notice auth-error" role="alert" hidden></div>${signup?'<label class="field">Full name<input name="name" autocomplete="name" required maxlength="100" placeholder="Your name"></label>':''}<label class="field">Email address<input type="email" name="email" autocomplete="email" required value="${esc(pendingEmail)}" placeholder="you@example.com"></label><label class="field">Password<input type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="8" placeholder="At least 8 characters"></label><button class="btn full" data-label="${signup?'Create account':'Log in'}" ${isDemo()?'disabled':''}>${signup?'Create account':'Log in'} ${icon('arrow')}</button></form><div class="form-foot">${signup?'Already a member?':'New around here?'} <button class="link" data-action="${signup?'login':'signup'}">${signup?'Log in':'Create account'}</button></div>${!signup?'<div class="form-foot"><button class="link" data-action="confirm-email">Need a confirmation email?</button></div>':''}`)}
function confirmationModal(email=''){modal('Check your email',`<div class="email-confirm-icon">${icon('send')}</div><p class="sub">You are not signed in yet. Email verification is required before you can log in.</p><div class="notice green">Check the inbox and spam folder for <strong>${esc(email||'your email address')}</strong>. Open the confirmation link, then return here and log in. If this email already has an account, try logging in instead.</div><div class="auth-steps"><span><b>1</b>Open the email from Supabase / Educate</span><span><b>2</b>Tap the confirmation link</span><span><b>3</b>Return to Educate Orders and log in</span></div><button class="btn full" data-action="login">I’ve confirmed · Log in ${icon('arrow')}</button><form id="resend-form"><label class="field">Send a new confirmation to<input name="email" type="email" required value="${esc(email)}" placeholder="you@example.com" autocomplete="email"></label><div id="resend-error" class="notice auth-error" role="alert" hidden></div><div id="resend-status" class="notice green" role="status" hidden></div><button class="btn light full">Resend confirmation email</button></form>`)}
const paymentOptions={collection:{label:'Pay on collection'},mtn:{label:'MTN MoMo',number:'0778722677',recipient:'Baluku Ronald'},airtel:{label:'Airtel Money',number:'0705994665',recipient:'Baluku Ronald'}};
function paymentLabel(o){return paymentOptions[o.payment_method||'collection']?.label||'Pay on collection'}
function paymentState(o){return o.payment_status==='Paid'?'Paid':o.payment_reference?'Awaiting staff verification':'Unpaid'}
function checkout(){if(!count())return;if(sb&&!session){authForm();return}modal('Checkout',`<p class="sub">Pickup from Educate · Main kitchen</p>${!navigator.onLine?'<div class="notice">Offline checkout saves a draft only. No order or payment is sent.</div>':''}<form id="checkout-form"><label class="field">Your name<input required name="name" maxlength="100" value="${esc(profile?.name||'')}" placeholder="Who is collecting?"></label><label class="field">Phone number<input required name="phone" type="tel" minlength="7" maxlength="24" placeholder="07XX XXX XXX"></label><label class="field">Payment method<select name="payment_method" id="checkout-payment"><option value="collection">Pay on collection</option><option value="mtn" ${paymentReady?'':'disabled'}>MTN MoMo · manual verification${paymentReady?'':' (setup pending)'}</option><option value="airtel" ${paymentReady?'':'disabled'}>Airtel Money · manual verification${paymentReady?'':' (setup pending)'}</option></select></label><div id="checkout-payment-info" class="notice green">Pay staff when you collect your order. Nothing is charged by this app.</div><label class="field">Collection notes<textarea name="notes" maxlength="500" placeholder="Special requests, allergies, pickup notes…"></textarea></label><div class="total-row final"><span>${count()} items · Total</span><span>${money(total())}</span></div><button class="btn full">${navigator.onLine?'Place order':'Save draft'} ${icon('arrow')}</button><p class="sub" style="margin-top:12px">Place your order first. Mobile Money instructions will show its confirmed total. Never enter your wallet PIN here.</p></form>`)}
function paymentDialog(id){const o=orders.find(x=>x.id===id);if(!o||o.customer_id!==customerId())throw Error('Order not available.');if(!paymentReady||!sb)throw Error('Mobile Money setup is not complete.');const p=paymentOptions[o.payment_method];if(!p?.number)throw Error('This order uses payment on collection.');if(o.status==='Draft'||o.status==='Cancelled'||o.payment_status==='Paid')throw Error('This order cannot accept a payment reference.');modal('Pay with '+p.label,`<p class="sub">${esc(o.number)} · payment checked manually by Educate staff</p><div class="payment-destination ${o.payment_method}"><span>${esc(p.label)}</span><strong>${esc(p.number)}</strong><small>Registered recipient: <b>${esc(p.recipient)}</b></small><div class="payment-amount">Amount to send <b>${money(o.total)}</b></div></div><div class="notice">Send from your own Mobile Money menu or provider app. Confirm the recipient is <strong>Baluku Ronald</strong> before approving. Cancel if the name differs. Network fees may apply. Never share your PIN.</div><form id="payment-reference-form" data-id="${o.id}"><label class="field">Transaction reference from the payment message<input name="reference" required minlength="4" maxlength="80" value="${esc(o.payment_reference||'')}" placeholder="Enter transaction ID" autocomplete="off"></label><label class="payment-check"><input type="checkbox" required> I have sent ${money(o.total)} to the number above.</label><div id="payment-error" class="notice auth-error" role="alert" hidden></div><button class="btn full" ${navigator.onLine?'':'disabled'}>${o.payment_reference?'Update reference':'Submit for staff verification'}</button></form><p class="sub" style="margin-top:14px">Submitting a reference does not confirm payment. Staff must verify the actual wallet credit. Do not send the payment twice while waiting.</p>`)}
function verifyPaymentDialog(id){if(!staff())throw Error('Staff access required.');const o=orders.find(o=>o.id===id);if(!o||o.payment_status==='Paid'||o.status==='Cancelled')throw Error('Order cannot be confirmed.');const mobile=o.payment_method&&o.payment_method!=='collection';if(mobile&&!o.payment_reference)throw Error('Wait for the customer’s transaction reference.');modal('Confirm money received',`<p class="sub">${esc(o.number)} · ${esc(o.customer_name)}</p><div class="payment-review"><span>Method <b>${esc(paymentLabel(o))}</b></span><span>Order total <b>${money(o.total)}</b></span>${mobile?`<span>Receiving number <b>${esc(paymentOptions[o.payment_method].number)}</b></span><span>Customer reference <b>${esc(o.payment_reference)}</b></span>`:''}</div><div class="notice">${mobile?'Open the receiving wallet and match the transaction reference, amount and recipient. A customer reference or screenshot alone is not proof of payment.':'Confirm the customer has paid you the full order total.'}</div><form id="verify-payment-form" data-id="${o.id}"><label class="payment-check"><input type="checkbox" required> I checked and received ${money(o.total)}${mobile?' in the receiving wallet':''}.</label><div id="payment-error" class="notice auth-error" role="alert" hidden></div><button class="btn full">Confirm received · Mark paid</button></form>`)}
function productForm(id){if(!staff()){toast('An admin or staff login is required.');return}let p=products.find(p=>p.id===id)||{};modal(p.id?'Edit a favourite':'Something new on the menu',`<p class="sub">Keep the good things coming.</p><form id="product-form" data-id="${p.id||''}"><label class="field">Product name<input name="name" required maxlength="100" value="${esc(p.name||'')}"></label><label class="field">Description<input name="description" required maxlength="200" value="${esc(p.description||'')}"></label><div style="display:flex;gap:12px"><label class="field" style="flex:1">Price (UGX)<input name="price" type="number" required min="1" step="1" value="${p.price||''}"></label><label class="field" style="flex:1">Unit<input name="unit" required maxlength="20" value="${esc(p.unit||'piece')}"></label></div><label class="field">Category<select name="category">${['Snacks','Bakery','Drinks'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Product photo<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="upload">Optional · JPG, PNG or WebP · up to 3 MB. Photos are cached after viewing.</p><label class="field">Availability<select name="available"><option value="true">Available</option><option value="false" ${p.available===false?'selected':''}>Hidden from the menu</option></select></label><button class="btn full">Save product ${icon('check')}</button></form>`)}
async function connect(){if(!config.url||!config.key)return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');sb=createClient(config.url,config.key);const {data}=await sb.auth.getSession();session=data.session;sb.auth.onAuthStateChange((_e,s)=>{session=s;setTimeout(()=>sync().catch(e=>toast(e.message)),0)});await sync();}catch(e){sb=null;toast('Could not connect: '+e.message)}render()}
async function sync(){if(!sb||!navigator.onLine)return;let r=await sb.from('products').select('*').order('created_at');if(r.error)throw r.error;products=r.data;const paymentProbe=await sb.from('orders').select('payment_method,payment_reference,payment_verified_at').limit(0);paymentReady=!paymentProbe.error; if(session){r=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(r.error)throw r.error;profile=r.data;const results=await Promise.all([sb.from('orders').select('*').order('created_at',{ascending:false}),sb.from('messages').select('*').order('created_at'),sb.from('feedback').select('*').order('created_at',{ascending:false})]);for(const x of results)if(x.error)throw x.error;orders=[...orders.filter(o=>o.status==='Draft'&&o.customer_id===session.user.id),...results[0].data];messages=results[1].data;feedback=results[2].data;if(role()==='admin'){r=await sb.from('profiles').select('*');if(r.error)throw r.error;store.set('profiles',r.data)}}else{profile=null;orders=orders.filter(o=>o.status==='Draft');messages=[];feedback=[]}save();subscribe();render()}
function subscribe(){if(!sb||channel)return;channel=sb.channel('educate-live').on('postgres_changes',{event:'*',schema:'public',table:'orders'},p=>{const incoming=p.new;const old=orders.find(o=>o.id===incoming.id);if(incoming.id&&(!old||old.status!==incoming.status)){notify(old?'Order updated: '+incoming.status:'New order received',incoming.number)}sync().catch(e=>toast(e.message))}).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages'},()=>{notify('New message','Open Educate Orders to read it.');sync().catch(e=>toast(e.message))}).on('postgres_changes',{event:'*',schema:'public',table:'products'},()=>sync().catch(e=>toast(e.message))).subscribe()}
function notify(t,b){toast(t+(b?' · '+b:''));if('Notification'in window&&Notification.permission==='granted'&&document.hidden)new Notification(t,{body:b,icon:'/icon-192.png'})}
async function submitOrder(o){if(!navigator.onLine)throw Error('Reconnect before submitting your order.');if(sb){if(!session)throw Error('Please log in first.');const check=await sb.from('products').select('id,price,available').in('id',o.items.map(i=>i.product_id));if(check.error)throw check.error;for(const i of o.items){const p=check.data.find(p=>p.id===i.product_id);if(!p||!p.available||p.price!==i.price){await sync();throw Error('Price or availability changed. Please review your basket.')}}if(o.payment_method&&o.payment_method!=='collection'&&!paymentReady)throw Error('Mobile Money setup is pending. Please choose pay on collection.');const {data,error}=await sb.rpc(paymentReady?'place_order_with_payment':'place_order',{...(paymentReady?{pay_method:o.payment_method||'collection'}:{}),basket:o.items.map(i=>({product_id:i.product_id,qty:i.qty})),buyer_name:o.customer_name,buyer_phone:o.phone,buyer_notes:o.notes||''});if(error)throw error;await sync();return data}for(let i of o.items){let p=products.find(p=>p.id===i.product_id);if(!p||!p.available)throw Error(i.name+' is no longer available.');if(p.price!==i.price)throw Error('Prices changed. Please review your basket.')}o.status='Received';o.customer_id=customerId();orders=orders.filter(x=>x.id!==o.id);orders.unshift(o);save();notify('Order received',o.number)}
async function updateOrder(id,patch){if(!staff())return;if(!navigator.onLine)throw Error('Reconnect to update orders.');if(sb){const {error}=await sb.from('orders').update(patch).eq('id',id);if(error)throw error;await sync()}else{Object.assign(orders.find(o=>o.id===id),patch);save();render();toast('Order updated')}}
function scrollChat(){setTimeout(()=>{let m=$('.messages');if(m)m.scrollTop=m.scrollHeight},20)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;try{if(a==='nav'){if(v==='admin'&&!staff()){authForm();toast('An admin or staff login is required.');return}view=v;close();render();window.scrollTo({top:0,behavior:'smooth'})}else if(a==='close')close();else if(a==='category'){category=v;render()}else if(a==='add'||a==='minus'){cart[v]=Math.max(0,(cart[v]||0)+(a==='add'?1:-1));if(!cart[v])delete cart[v];save();let wasCart=!!$('#modal-root .cart-panel');render();if(wasCart)modal('Your basket',cartPanel());else if(a==='add')toast('A little goodness added to your basket')}else if(a==='favourite'){favs=favs.includes(v)?favs.filter(x=>x!==v):[...favs,v];save();render()}else if(a==='browse')$('#menu').scrollIntoView({behavior:'smooth',block:'start'});else if(a==='cart')modal('Made for you',cartPanel());else if(a==='checkout')checkout();else if(a==='payment-details')paymentDialog(v);else if(a==='verify-payment')verifyPaymentDialog(v);else if(a==='login'||a==='signup')authForm(a==='signup');else if(a==='confirm-email'){const email=$('#auth-form [name=email]')?.value?.trim()||pendingEmail;confirmationModal(email)}else if(a==='rate'){rating=Number(v);document.querySelectorAll('.rating button').forEach((b,i)=>b.classList.toggle('on',i<rating))}else if(a==='admin-tab'){adminTab=v;render()}else if(a==='new-product'||a==='edit-product'){if(!staff())throw Error('Please log in with an admin or staff account.');productForm(v)}else if(a==='order-chat'){chatOrder=v;view='chat';render()}else if(a==='select-chat'){chatOrder=v;render()}else if(a==='submit-draft'){const o=orders.find(x=>x.id===v);await submitOrder(o);orders=orders.filter(x=>x.id!==v||x.status!=='Draft');save();render();toast('Order sent to the kitchen')}else if(a==='refresh'){if(sb)await sync();else render();toast('You’re up to date')}else if(a==='logout'){await sb.auth.signOut();profile=null;session=null;view='shop';await sync()}else if(a==='setup'){if(sb&&role()!=='admin')throw Error('Only the administrator can change the connection.');modal('Connect your kitchen',`<p class="sub">Run supabase.sql in your Supabase SQL Editor first. Then enter your public project credentials.</p><div class="notice">Use the publishable / anon key only. Never enter a secret or service-role key. Connecting replaces this device’s demo catalogue with your shared data.</div><form id="setup-form"><label class="field">Project URL<input required name="url" type="url" placeholder="https://your-project.supabase.co" value="${esc(config.url||'')}"></label><label class="field">Publishable / anon key<textarea required name="key" placeholder="sb_publishable_… or eyJ…">${esc(config.key||'')}</textarea></label><button class="btn full">Connect Supabase ${icon('arrow')}</button></form>`)}else if(a==='notifications'){let recent=myOrders().filter(o=>o.status!=='Draft').slice(0,5);modal('Your little updates',`<p class="sub">Order activity${isDemo()?' on this device':''}. In-app updates are live when Supabase is connected.</p>${recent.length?recent.map(o=>`<div class="review"><div><strong>${esc(o.number)}</strong><p class="sub">${esc(o.customer_name)}</p></div><span class="status">${esc(o.status)}</span></div>`).join(''):'<p class="sub">You’re all caught up. New order updates will appear here.</p>'}`)}else if(a==='notify-permission'){if(!('Notification'in window))throw Error('This browser does not support notifications. On iPhone, install the app first.');let p=await Notification.requestPermission();toast(p==='granted'?'Foreground notifications enabled. Background push needs server setup.':'Notification permission was not granted.')}else if(a==='install'){if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else modal('Keep us close.',`<p class="sub">On Android: open your browser menu and choose “Install app” or “Add to Home screen”.<br><br>On iPhone: open this app in Safari, tap Share, then “Add to Home Screen”.<br><br>Visit once while online to save the app for offline browsing.</p>`)}else if(a==='privacy')modal('Your data, with care.',`<p class="sub">In preview mode, products, carts, orders, chat and feedback are stored only in this browser. Clearing browser data removes them.<br><br>When connected, Supabase stores accounts, order details, phone numbers, messages and feedback. Customers can access their own orders; authorised staff can manage orders and chats; admins manage the catalogue and users.<br><br>Payment card details are never requested. This prototype supports payment records for collection only. Set your organisation’s privacy policy and retention rules before a public launch.</p>`)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='checkout-payment'){const p=paymentOptions[e.target.value];$('#checkout-payment-info').innerHTML=p.number?'After placing your order, send the confirmed total using <strong>'+esc(p.label)+'</strong> to <strong>'+esc(p.number)+'</strong>, recipient <strong>'+esc(p.recipient)+'</strong>. Then submit your transaction reference. Staff verify receipt manually.':'Pay staff when you collect your order. Nothing is charged by this app.';return}if(e.target.dataset.status)await updateOrder(e.target.dataset.status,{status:e.target.value});if(e.target.dataset.userRole){if(role()!=='admin')throw Error('Admin required');const {error}=await sb.from('profiles').update({role:e.target.value}).eq('id',e.target.dataset.userRole);if(error)throw error;await sync();toast('Role updated')}}catch(err){toast(err.message);render()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),btn=f.querySelector('button[type="submit"],button:not([type])');if(btn){btn.disabled=true;if(f.id==='auth-form'){btn.dataset.label=btn.dataset.label||(f.dataset.signup==='true'?'Create account':'Log in');btn.innerHTML='<span class="auth-spinner"></span> '+(f.dataset.signup==='true'?'Creating account…':'Signing in…');const error=f.querySelector('#auth-error');if(error)error.hidden=true}}try{if(f.id==='checkout-form'){let o={id:crypto.randomUUID(),number:'EO-'+Date.now().toString().slice(-6),customer_id:customerId(),customer_name:d.name,phone:d.phone,notes:d.notes,payment_method:d.payment_method||'collection',items:Object.entries(cart).map(([id,qty])=>{let p=products.find(p=>p.id===id);if(!p||!p.available)throw Error('An item is no longer available.');return {product_id:id,name:p.name,qty,price:p.price}}),total:total(),status:'Draft',payment_status:'Unpaid',created_at:new Date().toISOString()};if(navigator.onLine)await submitOrder(o);else orders.unshift(o);cart={};save();close();view='orders';render();toast(navigator.onLine?'Your order is with the kitchen. Thank you!':'Draft saved. Reconnect and submit it from My orders.')}else if(f.id==='payment-reference-form'){if(!sb||!session||!navigator.onLine)throw Error('Log in and reconnect to submit a payment reference.');if(!new RegExp('^[A-Za-z0-9 ._/-]{4,80}$').test(d.reference.trim()))throw Error('Enter the transaction reference using letters, numbers, spaces or . _ / - (4 to 80 characters).');const {error}=await sb.rpc('submit_payment_reference',{order_id:f.dataset.id,transaction_ref:d.reference.trim()});if(error)throw error;await sync();close();toast('Reference submitted. Payment remains unpaid until staff verify receipt.')}else if(f.id==='verify-payment-form'){if(!staff())throw Error('Staff access required.');await updateOrder(f.dataset.id,{payment_status:'Paid'});close();toast('Payment marked paid after your confirmation.')}else if(f.id==='feedback-form'){if(!navigator.onLine)throw Error('Reconnect to send feedback.');let item={id:crypto.randomUUID(),name:d.name,body:d.body,rating,created_at:new Date().toISOString(),customer_id:session?.user.id||null};if(sb){const {error}=await sb.from('feedback').insert(item);if(error)throw error}else feedback.unshift(item);save();f.reset();toast('Thank you. A little feedback makes a big difference.')}else if(f.id==='chat-form'){if(!navigator.onLine)throw Error('Reconnect to send a message.');let m={id:crypto.randomUUID(),order_id:chatOrder,sender_id:customerId(),sender_role:role(),body:d.body.trim(),created_at:new Date().toISOString()};if(!m.body)return;if(sb){const {error}=await sb.from('messages').insert(m);if(error)throw error;await sync()}else{messages.push(m);save();render()}f.reset();scrollChat()}else if(f.id==='auth-form'){if(!sb)throw Error('Connect Supabase first.');let signup=f.dataset.signup==='true';const {data,error}=signup?await sb.auth.signUp({email:d.email,password:d.password,options:{data:{name:d.name}}}):await sb.auth.signInWithPassword({email:d.email,password:d.password});if(error)throw error;pendingEmail=d.email.trim();store.set('pendingEmail',pendingEmail);session=data.session;if(signup&&!data.session){confirmationModal(pendingEmail)}else{view='account';await sync();close();toast('You are signed in. Welcome to Educate!')}}else if(f.id==='resend-form'){if(!sb)throw Error('The connection is not ready. Please try again.');const {error}=await sb.auth.resend({type:'signup',email:d.email.trim()});if(error)throw error;const status=$('#resend-status');if(status){status.hidden=false;status.textContent='Confirmation requested. Check your inbox and spam folder. If the account is already confirmed, log in instead.'}}else if(f.id==='setup-form'){if(sb&&role()!=='admin')throw Error('Only the administrator can change the connection.');if(d.key.startsWith('sb_secret_'))throw Error('Never use a secret key. Use the publishable key.');if(d.key.startsWith('eyJ')){try{if(JSON.parse(atob(d.key.split('.')[1])).role==='service_role')throw Error('Service-role keys are unsafe in the app.')}catch(err){if(err.message.includes('unsafe'))throw err}}config={url:d.url.replace(/\/$/,''),key:d.key.trim()};store.set('config',config);close();if(channel&&sb)await sb.removeChannel(channel);channel=null;await connect()}else if(f.id==='product-form'){if(!staff())throw Error('Please log in with an admin or staff account.');if(!navigator.onLine)throw Error('Reconnect to save products.');let old=products.find(p=>p.id===f.dataset.id);let p={id:old?.id||crypto.randomUUID(),name:d.name,description:d.description,price:Number(d.price),unit:d.unit,category:d.category,available:d.available==='true',kind:old?.kind||'mandazi',image_url:old?.image_url||null};if(!Number.isFinite(p.price)||p.price<1)throw Error('Enter a valid price.');let file=new FormData(f).get('photo');if(file?.size){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP photo.');if(file.size>3*1024*1024)throw Error('Choose a photo smaller than 3 MB.');if(sb){let path=crypto.randomUUID()+'.'+file.name.split('.').pop();let {error}=await sb.storage.from('product-images').upload(path,file);if(error)throw error;p.image_url=sb.storage.from('product-images').getPublicUrl(path).data.publicUrl}else p.image_url=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}if(sb){const {error}=await sb.from('products').upsert(p);if(error)throw error;await sync()}else{products=old?products.map(x=>x.id===old.id?p:x):[...products,p];save()}close();render();toast('Menu updated. Fresh possibilities!')}}catch(err){const notice=f.querySelector('#auth-error,#resend-error,#payment-error');if(notice){notice.hidden=false;notice.textContent=err.message==='Email not confirmed'?'Please confirm your email before logging in. Check your inbox and spam folder, or request a new confirmation email below.':err.message;notice.scrollIntoView({block:'nearest',behavior:'smooth'})}toast(err.message)}finally{if(btn){btn.disabled=false;if(btn.dataset.label)btn.innerHTML=esc(btn.dataset.label)+' '+icon('arrow')}}});
window.addEventListener('online',()=>{render();if(sb)sync().catch(e=>toast(e.message));toast('Back online. Saved drafts can now be submitted.')});window.addEventListener('offline',()=>{render();toast('You’re offline. Your saved menu and basket are still here.')});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});render();connect();
